/// Draw a single character from the 8x8 bitmap font.
#[inline]
pub fn draw_char(
    pixels: &mut [u8],
    stride: u32,
    fb_width: u32,
    fb_height: u32,
    ch: u8,
    x: u32,
    y: u32,
    r: u8,
    g: u8,
    b: u8,
) {
    let glyph = FONT_8X8[ch as usize & 0x7F];
    for row in 0..8u32 {
        let cy = y + row;
        if cy >= fb_height { return; }
        let row_start = (cy * stride) as usize;
        let bits = glyph[row as usize];
        for col in 0..8u32 {
            let cx = x + col;
            if cx >= fb_width { return; }
            if bits & (0x80 >> col) != 0 {
                let i = row_start + (cx as usize) * 4;
                pixels[i] = b;
                pixels[i + 1] = g;
                pixels[i + 2] = r;
            }
        }
    }
}

/// Draw a string of text.
#[inline]
pub fn draw_text(
    pixels: &mut [u8],
    stride: u32,
    fb_width: u32,
    fb_height: u32,
    text: &str,
    x: u32,
    y: u32,
    r: u8,
    g: u8,
    b: u8,
) {
    let mut cx = x;
    for &byte in text.as_bytes() {
        if cx + 8 > fb_width { break; }
        draw_char(pixels, stride, fb_width, fb_height, byte, cx, y, r, g, b);
        cx += 8;
    }
}
